package com.ahdre.pip;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.net.*;import java.io.*;import org.json.*;

class SocialClient {
 static final String ENDPOINT="https://ntfy.sh";
 static FriendsRelay sharedRelay;FriendsRelay relay;
 static synchronized FriendsRelay relay(SharedPreferences p)throws Exception{if(sharedRelay==null)sharedRelay=new FriendsRelay(p);return sharedRelay;}
 static class Pet {String id,name,code;int accessory;boolean accepted,incoming,online;Pet(JSONObject p){id=p.optString("id");name=p.optString("name","Пип");code=p.optString("code");accessory=p.optInt("accessory");accepted=p.optBoolean("accepted");incoming=p.optBoolean("incoming");online=p.optBoolean("online");}}
 final Context context;final SharedPreferences prefs;final Handler handler=new Handler(Looper.getMainLooper());boolean busy=false,closed=false;String pendingRoute;JSONObject pendingData;long poll=0;JSONObject state=new JSONObject();String message="Сеть выключена";Runnable updated;
 SocialClient(Context c){context=c;prefs=c.getSharedPreferences("pip",0);try{relay=relay(prefs);}catch(Exception e){message="Не удалось подготовить ключи связи";}}
 void tick(){if(!prefs.getBoolean("socialEnabled",false)){state=new JSONObject();return;}long now=SystemClock.uptimeMillis();if(now>=poll&&!busy){poll=now+10000;call("/state",new JSONObject());}}
 boolean away(){if(!prefs.getBoolean("socialEnabled",false))return false;JSONArray a=state.optJSONArray("visits");if(a!=null)for(int i=0;i<a.length();i++){JSONObject v=a.optJSONObject(i);if(v!=null&&v.optString("status").equals("active")&&v.optBoolean("outgoing"))return true;}return false;}
 Pet visitor(){if(!prefs.getBoolean("socialEnabled",false))return null;JSONArray a=state.optJSONArray("visits");if(a!=null)for(int i=0;i<a.length();i++){JSONObject v=a.optJSONObject(i);if(v!=null&&v.optString("status").equals("active")&&!v.optBoolean("outgoing"))return new Pet(v.optJSONObject("pet"));}return null;}
 void call(final String route,JSONObject p){if(closed)return;if(busy){if(!route.equals("/state")){pendingRoute=route;pendingData=p;message="Отправлю после проверки связи…";notifyUI();}return;}if(!prefs.getBoolean("socialEnabled",false)&&!route.equals("/disconnect")){message="Сначала включи друзей через интернет";notifyUI();return;}if(relay==null){message="Не удалось подготовить ключи связи";notifyUI();return;}
  final JSONObject data=p;final String localName=prefs.getString("socialName","Пип");final int acc=prefs.getInt("accessory",0);busy=true;
  new Thread(new Runnable(){public void run(){JSONObject result=null;String error=null;try{result=relay.perform(route,data,localName,acc);}catch(Exception e){error=e.getMessage();if(error==null||error.length()>180)error="Нет связи. Пип вернулся домой.";}final JSONObject answer=result;final String failure=error;
   handler.post(new Runnable(){public void run(){busy=false;if(closed)return;if(failure!=null){message=failure;state=new JSONObject();}else if(answer!=null){state=prefs.getBoolean("socialEnabled",false)?answer:new JSONObject();message=prefs.getBoolean("socialEnabled",false)?"Связь ntfy · проверка каждые 10 секунд.":"Сеть выключена";}notifyUI();if(pendingRoute!=null){String next=pendingRoute;JSONObject data=pendingData;pendingRoute=null;pendingData=null;call(next,data);}}});
  }}).start();
 }
 void notifyUI(){if(updated!=null)updated.run();}
 void close(){closed=true;handler.removeCallbacksAndMessages(null);state=new JSONObject();}
 static void open(final MainActivity a){final SocialClient client=new SocialClient(a);final LinearLayout page=new LinearLayout(a);page.setOrientation(1);page.setPadding(a.dp(12),a.dp(12),a.dp(12),a.dp(12));ScrollView scroll=new ScrollView(a);scroll.addView(page);
  a.label(page,"Бесплатная связь через ntfy без регистрации. Передавай код лично. Каждый визит принимает хозяин. Пип гостит 3 минуты; при потере связи визит завершится.",14);
  final Switch enabled=new Switch(a);enabled.setText("Друзья через интернет");enabled.setChecked(client.prefs.getBoolean("socialEnabled",false));page.addView(enabled);enabled.setOnCheckedChangeListener(new CompoundButton.OnCheckedChangeListener(){public void onCheckedChanged(CompoundButton v,boolean on){client.prefs.edit().putBoolean("socialEnabled",on).apply();if(!on){client.state=new JSONObject();client.call("/disconnect",new JSONObject());}else client.poll=0;client.notifyUI();}});
  a.label(page,"Имя твоего Пипа",14);final EditText name=new EditText(a);name.setSingleLine(true);name.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(24)});name.setText(client.prefs.getString("socialName","Пип"));page.addView(name);
  a.addButton(page,"Сохранить имя",new View.OnClickListener(){public void onClick(View v){if(!name.getText().toString().trim().isEmpty()){client.prefs.edit().putString("socialName",name.getText().toString().trim()).apply();client.poll=0;}}});
  final TextView status=a.label(page,"",14);a.addButton(page,"Скопировать мой код друга",new View.OnClickListener(){public void onClick(View v){String code=client.prefs.getString("socialCode","");if(!code.isEmpty()){android.content.ClipboardManager cb=(android.content.ClipboardManager)a.getSystemService(Context.CLIPBOARD_SERVICE);cb.setPrimaryClip(ClipData.newPlainText("Код друга Пипа",code));Toast.makeText(a,"Код скопирован",Toast.LENGTH_SHORT).show();}}});
  final EditText code=new EditText(a);code.setSingleLine(true);code.setHint("Код друга");code.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(90)});page.addView(code);
  a.addButton(page,"Добавить друга по коду",new View.OnClickListener(){public void onClick(View v){JSONObject p=new JSONObject();try{p.put("code",code.getText().toString().trim());}catch(Exception e){}client.call("/friend/request",p);}});
  final Spinner friends=new Spinner(a);page.addView(friends);final JSONArray[] rows={new JSONArray()};
  String[] titles={"Принять выбранного друга","Удалить друга / отклонить запрос","Отправить своего Пипа в гости","Принять входящий визит","Вернуть домой / завершить визит"};final String[] routes={"/friend/accept","/friend/remove","/visit/request","/visit/accept","/visit/end"};for(int i=0;i<titles.length;i++){final int index=i;a.addButton(page,titles[i],new View.OnClickListener(){public void onClick(View v){JSONObject p=new JSONObject();try{if(index<3){int pos=friends.getSelectedItemPosition();if(pos<0||pos>=rows[0].length()){client.message="Выбери друга";client.notifyUI();return;}p.put("friend",rows[0].getJSONObject(pos).getString("id"));}else if(index==3){JSONArray visits=client.state.optJSONArray("visits");String visit="";if(visits!=null)for(int j=0;j<visits.length();j++){JSONObject r=visits.getJSONObject(j);if(!r.optBoolean("outgoing")&&r.optString("status").equals("pending"))visit=r.getString("id");}if(visit.isEmpty()){client.message="Нет входящего визита";client.notifyUI();return;}p.put("visit",visit);}client.call(routes[index],p);}catch(Exception e){}}});}
  client.updated=new Runnable(){public void run(){String text="Мой код: "+client.prefs.getString("socialCode","появится после подключения")+"\n"+client.message;JSONArray visits=client.state.optJSONArray("visits");if(visits!=null)for(int i=0;i<visits.length();i++){JSONObject v=visits.optJSONObject(i);if(v!=null)text+="\n"+(v.optString("status").equals("pending")?(v.optBoolean("outgoing")?"Ждём разрешения на визит":"Есть входящий визит"):(v.optBoolean("outgoing")?"Пип гостит у друга":"Пип друга в гостях"));}status.setText(text);int selected=friends.getSelectedItemPosition();JSONArray arr=client.state.optJSONArray("friends");rows[0]=arr==null?new JSONArray():arr;String[] names=new String[rows[0].length()];for(int i=0;i<names.length;i++){Pet p=new Pet(rows[0].optJSONObject(i));names[i]=p.name+" · "+(p.accepted?(p.online?"недавно в сети":"доступность при визите"):p.incoming?"входящий запрос":"ожидает подтверждения");}ArrayAdapter<String> adapter=new ArrayAdapter<String>(a,android.R.layout.simple_spinner_item,names);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);friends.setAdapter(adapter);if(selected>=0&&selected<names.length)friends.setSelection(selected);}};
  AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Друзья и визиты").setView(scroll).setPositiveButton("Закрыть",null).create();dialog.setOnDismissListener(new DialogInterface.OnDismissListener(){public void onDismiss(DialogInterface d){client.close();}});dialog.show();client.notifyUI();client.handler.post(new Runnable(){public void run(){if(client.closed)return;if(client.prefs.getBoolean("enabled",false)&&dialog.isShowing()&&dialog.getWindow()!=null&&dialog.getWindow().getDecorView().hasWindowFocus()&&((android.os.PowerManager)a.getSystemService(Context.POWER_SERVICE)).isInteractive())client.tick();client.handler.postDelayed(this,1000);}});
 }
}
